-- Standardized Philippine locations (PSA PSGC), built in as static reference data (no external API).
-- The rows are loaded by 20261118000002_psgc_data.sql (generated by supabase/scripts/build_psgc_seed.ts).
-- Barangays are not loaded: they stay free text. Additive only; the old free-text columns are kept.

create table if not exists public."psgc_release" (
  "release" text primary key,
  "source" text not null,
  "provinces" integer not null,
  "cities" integer not null,
  "municipalities" integer not null,
  "sub_municipalities" integer not null,
  "loaded_at" timestamptz not null default now()
);

-- 82 provinces + the pseudo-provinces "Metro Manila (NCR)" and "BARMM Special Geographic Area".
create table if not exists public."psgc_provinces" (
  "code" text primary key,
  "name" text not null,
  "region_code" text not null,
  "region_name" text not null,
  "kind" text not null default 'province' check ("kind" in ('province', 'ncr', 'sga'))
);

-- Cities and municipalities under their (geographic) province. Manila's sub-municipalities are kept
-- for reference but are not selectable (the district is typed in the Barangay field).
create table if not exists public."psgc_cities" (
  "code" text primary key,
  "name" text not null,
  "official_name" text not null,
  "kind" text not null check ("kind" in ('city', 'municipality', 'sub_municipality')),
  "province_code" text not null references public."psgc_provinces" ("code"),
  "official_parent_code" text,
  "selectable" boolean not null default true
);
create index if not exists "psgc_cities_province_code_index" on public."psgc_cities" ("province_code");

-- Read-only reference data: RLS on with no policies (the API reads it; users cannot write it).
alter table public."psgc_release" enable row level security;
alter table public."psgc_provinces" enable row level security;
alter table public."psgc_cities" enable row level security;

-- Structured locations: {province_code, province, city_code, city, barangay, street}. The inquiry keeps
-- its own values; the applicant gets a copy at conversion (and edits of the inquiry stay in sync).
alter table public."franchise_inquiries" add column if not exists "residence_location" jsonb;
alter table public."franchise_inquiries" add column if not exists "preferred_location" jsonb;
alter table public."franchise_inquiries" add column if not exists "no_preferred_location" boolean not null default false;
alter table public."applicants" add column if not exists "residence_location" jsonb;
alter table public."applicants" add column if not exists "preferred_location" jsonb;
alter table public."applicants" add column if not exists "no_preferred_location" boolean not null default false;
